#!/usr/bin/env node
/**
 * Vendors WAAI's module API contract (docs/WAAI-NATIVE-MODULE.md §4.5).
 *
 *   npm run sync:waai-contract              copy the contract into src/components/whatsapp/api/contract.ts
 *   npm run sync:waai-contract -- --check   fail (exit 1) when the vendored copy differs from WAAI's
 *
 * The source is `packages/module-api/src/types.ts` in the WAAI repository: plain TypeScript types, no
 * imports. Where that repository is: `$WAAI_REPO`, else the `waai-native` worktree, else `waai-ccrm`, both
 * next to `ccrm/` under `01_My_web_apps`. The generated file starts with a header naming the WAAI commit;
 * `--check` compares everything below the header only, so a WAAI commit that does not touch the contract
 * does not make it fail.
 */
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(fileURLToPath(new URL('../', import.meta.url)));
const TARGET = path.join(root, 'src/components/whatsapp/api/contract.ts');
const SOURCE_IN_REPO = 'packages/module-api/src/types.ts';
const MARKER = '// ---- vendored contract below: do not edit above or below this line by hand ----';

function findRepo() {
  const candidates = [
    process.env.WAAI_REPO,
    path.resolve(root, '../../../01_My_web_apps/waai-native'),
    path.resolve(root, '../../../01_My_web_apps/waai-ccrm'),
  ].filter(Boolean);
  for (const dir of candidates) {
    if (fs.existsSync(path.join(dir, SOURCE_IN_REPO))) return dir;
  }
  return null;
}

const git = (repo, ...args) => {
  try {
    return execFileSync('git', ['-C', repo, ...args], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim();
  } catch {
    return '';
  }
};

const normalize = (text) => text.replace(/\r\n/g, '\n').replace(/\s+$/, '') + '\n';
const bodyOf = (text) => {
  const normalized = normalize(text);
  const at = normalized.indexOf(MARKER);
  return at === -1 ? normalized : normalized.slice(at + MARKER.length).replace(/^\n+/, '');
};

const check = process.argv.includes('--check');
const repo = findRepo();
if (!repo) {
  console.error(`The WAAI repository was not found (looked for ${SOURCE_IN_REPO}). Set WAAI_REPO to its path.`);
  process.exit(check ? 1 : 2);
}

const source = normalize(fs.readFileSync(path.join(repo, SOURCE_IN_REPO), 'utf8'));
if (/^\s*import\s/m.test(source) || /^\s*export\s+.*\sfrom\s/m.test(source)) {
  console.error(`${SOURCE_IN_REPO} must not import anything: the contract is copied as one self-contained file.`);
  process.exit(2);
}

if (check) {
  const have = fs.existsSync(TARGET) ? bodyOf(fs.readFileSync(TARGET, 'utf8')) : null;
  if (have !== source) {
    console.error(have === null ? 'src/components/whatsapp/api/contract.ts is missing.' : 'src/components/whatsapp/api/contract.ts differs from WAAI\'s contract.');
    console.error('Run: npm run sync:waai-contract');
    process.exit(1);
  }
  console.log('The vendored WAAI contract is up to date.');
  process.exit(0);
}

const commit = git(repo, 'rev-parse', '--short', 'HEAD') || 'unknown';
const branch = git(repo, 'rev-parse', '--abbrev-ref', 'HEAD') || 'unknown';
const dirty = git(repo, 'status', '--porcelain', '--', SOURCE_IN_REPO) ? ' (with uncommitted changes)' : '';
const header = [
  '// GENERATED by `npm run sync:waai-contract`. Do not edit: change WAAI\'s packages/module-api/src/types.ts and run it again.',
  `// Source: WAAI ${SOURCE_IN_REPO} @ ${commit} on ${branch}${dirty}`,
  MARKER,
  '',
].join('\n');

fs.mkdirSync(path.dirname(TARGET), { recursive: true });
fs.writeFileSync(TARGET, header + '\n' + source);
console.log(`Wrote ${path.relative(root, TARGET)} from ${path.join(repo, SOURCE_IN_REPO)} @ ${commit}.`);
